def learn_path(frames):
    """Track each element frame to frame; every move must follow one fixed successor map of positions."""
    succ = {}
    for a, b in zip(frames, frames[1:]):
        where = {sym: pos for pos, sym in b.items()}
        for pos, sym in a.items():
            nxt = where[sym]
            assert succ.setdefault(pos, nxt) == nxt, "elements do not share one path"
    return succ

def predict(frames):
    succ = learn_path(frames)
    return {succ[pos]: sym for pos, sym in frames[-1].items()}

def solve(frames, options):
    nxt = predict(frames)
    hits = [k for k, o in options.items() if o == nxt]
    assert len(hits) == 1, hits
    return hits[0]

