def next_count(counts):
    d = {b - a for a, b in zip(counts, counts[1:])}
    if len(d) == 1:
        return counts[-1] + d.pop()
    d2 = {(c - b) - (b - a) for a, b, c in zip(counts, counts[1:], counts[2:])}
    assert len(d2) == 1, "no constant change"
    return counts[-1] + (counts[-1] - counts[-2]) + d2.pop()

SIDES = ["UR", "UL", "L", "LL", "LR", "R"]      # hexagon sides, anticlockwise

def next_side(sides):
    steps = {(SIDES.index(b) - SIDES.index(a)) % 6 for a, b in zip(sides, sides[1:])}
    assert len(steps) == 1
    return SIDES[(SIDES.index(sides[-1]) + steps.pop()) % 6]

