POS = ["TL", "MM", "MR", "BL", "BM", "BR"]

def mapping(a, b):
    """Where each symbol of frame a sits in frame b; a symbol that vanished maps to None."""
    where = {s: p for p, s in b.items()}
    return {p: where.get(s) for p, s in a.items()}

def apply(m, frame, new):
    out = {}
    for p, s in frame.items():
        if m[p] is not None:
            out[m[p]] = s
    for p in POS:
        if p not in out:
            out[p] = new
    return out

