# 5x5 bitmaps, rows top to bottom
GLYPH = {
    "b": ["#....", "#....", "####.", "#...#", "####."],
    "d": ["....#", "....#", ".####", "#...#", ".####"],
    "p": ["####.", "#...#", "####.", "#....", "#...."],
    "q": [".####", "#...#", ".####", "....#", "....#"],
    "J": ["..###", "...#.", "...#.", "#..#.", ".##.."],
    "M": ["#...#", "##.##", "#.#.#", "#...#", "#...#"],
    "W": ["#...#", "#...#", "#.#.#", "##.##", "#...#"],
    "X": ["#...#", ".#.#.", "..#..", ".#.#.", "#...#"],
    "U": ["#...#", "#...#", "#...#", "#...#", ".###."],
    "H": ["#...#", "#...#", "#####", "#...#", "#...#"],
}

def word(text):
    """Bitmap of a word: glyphs side by side with a blank column between."""
    rows = [""] * 5
    for i, ch in enumerate(text):
        for r in range(5):
            rows[r] += ("." if i else "") + GLYPH[ch][r]
    return rows

def flip_lr(rows):
    return [r[::-1] for r in rows]

def flip_tb(rows):
    return rows[::-1]

def mirror_rule(tokens):
    """Vertical mirror: reverse the order and flip every glyph left-right; laterally symmetric glyphs stay."""
    out = []
    for g in reversed(tokens):
        out.append(g if g in SYMMETRIC_LR else (g[:-1] if g.endswith("'") else g + "'"))
    return out

SYMMETRIC_LR = {g for g in GLYPH if flip_lr(GLYPH[g]) == GLYPH[g]}
assert SYMMETRIC_LR == {"M", "W", "X", "U", "H"}

# the rule matches a true pixel reflection of the whole word
for w in ["MJXWU", "bd", "JUMX"]:
    picture = flip_lr(word(w))
    rebuilt = [""] * 5
    for i, g in enumerate(mirror_rule(list(w))):
        bm = flip_lr(GLYPH[g[0]]) if g.endswith("'") else GLYPH[g]
        for r in range(5):
            rebuilt[r] += ("." if i else "") + bm[r]
    assert picture == rebuilt, w
assert flip_lr(GLYPH["b"]) == GLYPH["d"]                  # b in a side mirror reads as d
assert flip_lr(GLYPH["b"]) != flip_tb(GLYPH["b"])         # a water flip is a different picture

