from fractions import Fraction as Fr

def reflect(p, fold):
    axis, c = fold
    x, y = p
    return (2 * c - x, y) if axis == "x" else (x, 2 * c - y)

def unfold(holes, folds):
    """Undo the folds in reverse order; each hole gains its mirror image across that fold line."""
    pts = set(holes)
    for fold in reversed(folds):
        pts |= {reflect(p, fold) for p in pts}
    return pts

