from fractions import Fraction as Fr

def reflect_y(p, c):
    return (p[0], 2 * c - p[1])

def clip(seg, lo, hi):
    """Part of a straight segment with lo <= y <= hi (exact)."""
    (x1, y1), (x2, y2) = seg
    if y1 == y2:
        return seg if lo <= y1 <= hi else None
    t = sorted([Fr(lo - y1, y2 - y1), Fr(hi - y1, y2 - y1)])
    t0, t1 = max(t[0], 0), min(t[1], 1)
    if t0 >= t1:
        return None
    pt = lambda t: (x1 + t * (x2 - x1), y1 + t * (y2 - y1))
    return (pt(t0), pt(t1))

def fold_down(segs, heads, c, top):
    """Fold the half above y = c onto the half below and superimpose (sheet height `top`)."""
    out = set()
    for s in segs:
        below = clip(s, 0, c)
        above = clip(s, c, top)
        if below:
            out.add(frozenset(below))
        if above:
            out.add(frozenset(reflect_y(p, c) for p in above))
    hs = {reflect_y(p, c) if p[1] > c else p for p in heads}
    return out, hs

